"""Known-answer and discipline tests for TinyBisectWindowTool (au1k #30)."""

import unittest

from agentuniverse.agent.action.tool.common_tool.au_30_tiny_bisect_window import TinyBisectWindowTool


class TestTinyBisectWindowTool(unittest.TestCase):
    def _tool(self):
        return TinyBisectWindowTool()

    def test_run_matches_frozen_answers(self):
        tool = self._tool()
        self.assertEqual(tool.execute(action="run", x=[1, 2, 3, 50, 51, 52])["result"], {'bias': 'left', 'count': 6, 'pivot': 50.0, 'window': {'low': 49.0, 'high': 51.0}, 'lo_index': 3, 'hi_index': 5, 'inside': 2, 'sample': [50.0, 51.0], 'truncated': False})  # a
        self.assertEqual(tool.execute(action="run", x=[1, 2, 3, 5, 4, 3, 2, 9, 9, 10])["result"], {'bias': 'left', 'count': 10, 'pivot': 4.0, 'window': {'low': 3.0, 'high': 5.0}, 'lo_index': 3, 'hi_index': 7, 'inside': 4, 'sample': [3.0, 3.0, 4.0, 5.0], 'truncated': False})  # b

    def test_alt_action_runs_and_matches_canned_answer(self):
        tool = self._tool()
        got = tool.execute(action="alt", x=[1, 2, 3, 50, 51, 52])
        self.assertIsInstance(got["result"], dict)
        self.assertEqual(got["action"], "alt")
        self.assertEqual(got["result"], {'bias': 'left', 'count': 6, 'pivot': 50.0, 'window': {'low': 48.0, 'high': 52.0}, 'lo_index': 3, 'hi_index': 6, 'inside': 3, 'sample': [50.0, 51.0, 52.0], 'truncated': False})

    def test_meta_provenance(self):
        meta = self._tool().execute(action="meta", x=None)
        self.assertEqual(meta["series"], "au1k")
        self.assertEqual(meta["index"], 30)
        self.assertEqual(meta["algo"], 'au_algo_030')
        self.assertEqual(meta["params"], {'p1': 1, 'p2': 10, 'p3': True, 'p4': 'left'})
        self.assertEqual(meta["semantic"], 'tiny_bisect_window')

    def test_explicit_same_param_override_is_noop(self):
        tool = self._tool()
        self.assertEqual(tool.execute(action="run", x=[1, 2, 3, 50, 51, 52], p1=1, p2=10, p3=True, p4='left')["result"], {'bias': 'left', 'count': 6, 'pivot': 50.0, 'window': {'low': 49.0, 'high': 51.0}, 'lo_index': 3, 'hi_index': 5, 'inside': 2, 'sample': [50.0, 51.0], 'truncated': False})

    def test_repeat_determinism(self):
        tool = self._tool()
        one = tool.execute(action="run", x=[1, 2, 3, 50, 51, 52])["result"]
        two = tool.execute(action="run", x=[1, 2, 3, 50, 51, 52])["result"]
        self.assertEqual(one, two)

    def test_malformed_2_raises(self):
        tool = self._tool()
        with self.assertRaises(ValueError):
            tool.execute(action="run", x='')

    def test_unknown_action_raises(self):
        tool = self._tool()
        with self.assertRaises(ValueError):
            tool.execute(action="nope", x=[1, 2, 3, 50, 51, 52])


if __name__ == "__main__":
    unittest.main()
